#define COLOR(COORD) texture(iChannel0,(COORD))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{  

	vec2 uv = fragCoord.xy/iResolution.xy;    
    vec3 color = COLOR(uv).rgb;
    // effect sammple
    vec3 fgclr = vec3(0.);
    float f = length(uv  - 1.75);
    fgclr.x = COLOR(uv - vec2(f*0.002, .004)).x;
    fgclr.y = COLOR(uv + vec2(f*0.002, .000)).y;
    fgclr.z = COLOR(uv + vec2(f*0.004, .002)).z;

    // mask for effect and mixdown 
    float dt = distance(uv.xy,vec2(.5))*2.15;
    dt = smoothstep(0.1,.95,1.-dt);
    vec3 C = mix(fgclr,color,dt);//vec3(dt);//
    // output -gamma correct
    fragColor = vec4(pow(C, vec3(0.4545)),1.);

}

/** 

