#define R     iResolution
#define T     iTime
#define M     iMouse

#define PI    3.141592653
#define PI2   6.283185307

#define MIN_DIST    1e-4
#define MAX_DIST    50.

const float N = 4.;
const float s4 = .577350, s3 = .288683, s2 = .866025;
const vec2 s = vec2(1.732,1);

vec3 clr, trm,hit,hp;
float tk, ln, speed, time;
mat2 r2,r3;

mat2 rot(float g) { return mat2(cos(g), sin(g),-sin(g), cos(g)); }
float hash21(vec2 p) { return fract(sin(dot(p,vec2(26.37,45.93)))*4374.23); }

// Hexagon grid system
vec4 hexgrid(vec2 uv) {
    vec2 p1 = floor(uv/vec2(1.732,1))+.5,
         p2 = floor((uv-vec2(1,.5))/vec2(1.732,1))+.5;
    vec2 h1 = uv- p1*vec2(1.732,1),
         h2 = uv-(p2+.5)*vec2(1.732,1);
    return dot(h1,h1) < dot(h2,h2) ? vec4(h1,p1) : vec4(h2,p2+.5);
}

float opx(in float d, in float z, in float h){
    vec2 w = vec2( d, abs(z) - h );
  	return min(max(w.x, w.y), 0.) + length(max(w, 0.));
}

vec2 map(vec3 pos){
    vec2 res = vec2(1e5,0);
    vec2 uv = pos.xz;

    float sc = 1.25;
    float py = pos.y;

    vec4 H = hexgrid(uv*sc);
    vec2 p = H.xy, id = H.zw, p4, p5;

    float hs = hash21(id);

    if(hs<.5) p *= hs < .25 ? r3 : r2;

    vec2 p0 = p - vec2(-s3, .5),
         p1 = p - vec2( s4,  0),
         p2 = p - vec2(-s3,-.5);

    vec3 d3 = vec3(length(p0), length(p1), length(p2));
    vec2 pp = vec2(0);

    if(d3.x>d3.y) pp = p1;
    if(d3.y>d3.z) pp = p2;
    if(d3.z>d3.x && d3.y>d3.x) pp = p0;

    // base tile and empty vars
    float b = length(pp)-s3;
    float t = 1e5, g = 1e5, st = 0.;

    hs = fract(hs*53.71);

    // alternate tiles
    if(hs>.92) {
        p4 = p*r3, p5 = p*r2;
        b = length(vec2(p.x,abs(p.y)-.5));
        g = length(p5.x);
        t = length(p4.x);

        st = 1.;
    } else if(hs>.55) {
        b = length(p.x);
        g = min(length(p1)-s3,length(p1+vec2(1.155,0))-s3);
        st = 2.;
    } else if(hs<.15) {
        p4 = p*r3, p5 = p*r2;
        b = length(p.x);
        g = length(p5.x);
        t = length(p4.x);

        st = 1.;
    } else if(hs<.20) {
        b = length(vec2(p.x,abs(p.y)-.5));
        g = min(length(p1)-s3,length(p1+vec2(1.155,0))-s3);

    }

    float ty = st ==1.? py+(.13+.13*cos(p4.y*PI2)) : py;
    float gy = st ==1.? py-(.12+.12*cos(p5.y*PI2)) : py;
    float by = st ==2.? py-(.06+.06*cos(p.y*PI2)) : py;

    float l = .12, k = l*.6, ht = .0185;
    float db = opx(abs(abs(b)-l)-k,by,ht)-.0045;
    if(db<res.x) res = vec2(db,1.);

    float dg = opx(abs(abs(g)-l)-k,gy,ht)-.0045;
    if(dg<res.x) res = vec2(dg,2.);

    float dt = opx(abs(abs(t)-l)-k,ty,ht)-.0045;
    if(dt<res.x) res = vec2(dt,3.);

    return res;
}

vec3 normal(vec3 p, float t) {
    t*=MIN_DIST;
    float d = map(p).x;
    vec2 e = vec2(t,0);
    vec3 n = d - vec3(
        map(p-e.xyy).x,
        map(p-e.yxy).x,
        map(p-e.yyx).x
    );
    return normalize(n);
}

void mainImage( out vec4 O, in vec2 F ) {

    time =  T;

    speed = time*-2.55;
    r2 = rot( 1.047);
    r3 = rot(-1.047);

    // uv ro + rd
    vec2 uv = (2.* F.xy-R.xy)/max(R.x,R.y);

    vec3 ro = vec3(0,0,2.65);
    vec3 rd = normalize(vec3(uv,-1));

    float dof = 0.001;
    float dofdist = 1.0/6.;
    vec2 off=vec2(.05);

    // mouse //
    float x = M.xy==vec2(0) || M.z <0. ? 0. : -(M.y/R.y*.2-.1)*PI;
    float y = M.xy==vec2(0) || M.z <0. ? 0. : -(M.x/R.x*2.-1.)*PI;

    mat2 rx =rot(-.45-.55*sin(time*.4)-x);
    mat2 ry =rot(-.2-y+time*.3);

    ro.zy*=rx, ro.xz*=ry;
    rd.zy*=rx, rd.xz*=ry;

    ro.z+=speed;
    vec3 C=vec3(0);
    vec3 p = ro;

    float d = 0., m = 0.;
    for(int i=0;i<128;i++){    
        vec2 t = map(p);
        d += i<32? t.x*.5:t.x;
        m  = t.y;  

        //modified jitter/dof 
        //inspiration @Nusan https://www.shadertoy.com/view/3sXyRN
        if(mod(float(i),2.)<1.){
            off= texture(iChannel0,F.xy/1024.).rg*2.-1.;
            vec2 fp = off*dof;
            ro.xz+= fp*(d)*.003;
            rd.xy+= fp*(d*d)*dofdist*.06;
        }

        p = ro + rd * d;
        if(t.x<d*MIN_DIST||d>MAX_DIST) break;
    } 
    hp = hit;

    if(d<MAX_DIST) {

        vec3 n = normal(p,d);
        vec3 lpos = vec3(5,11,-15.+speed);
        vec3 l = normalize(lpos-p);
        float shdw = 1.;
        float diff = clamp(dot(n,l),0.,1.);
        for( float t=.01;t<10.; ) {
            float h = map(p + l*t).x;
            if( h<MIN_DIST ) { shdw = 0.; break; }
            shdw = min(shdw, 24.*h/t);
            t += h * .9;
            if( shdw<MIN_DIST || t>15. ) break;
        }

        vec3 h = vec3(.2,.0,.9);
        h = mix(h,h*diff,.45);
        C = mix(h,h*shdw,.45);

    }

    C = mix(C,vec3(.03,.0,.1), 1.-exp(-.003*d*d*d));

    //C = pow(C,vec3(.4545));
    O = vec4(C,1);
}

